src = r'''
import json, numpy as np
def load(k): return json.load(open(f'pass_{k}/meta.json'))
m1=load(1); lab1=np.array(m1['labels'])
Lb=np.load('pass_1/logits.npy')
def f1(pe,lab):
    f=[]
    for c in range(4):
        tp=((pe==c)&(lab==c)).sum(); fp=((pe==c)&(lab!=c)).sum(); fn=((pe!=c)&(lab==c)).sum()
        f.append(2*tp/(2*tp+fp+fn))
    return np.mean(f)
def stats(k, L=None, verbose=True):
    if L is None:
        m=load(k); assert m['ids']==m1['ids']
        L=np.load(f'pass_{k}/logits.npy')
    pb=Lb.argmax(1); pe=L.argmax(1)
    srt=np.sort(Lb,1); marg=srt[:,-1]-srt[:,-2]; low=marg<np.quantile(marg,0.2)
    r2=1-((L-Lb)**2).sum()/((Lb-Lb.mean(0))**2).sum()
    out=[]
    if k is not None:
      for l in range(7):
        try:
            hb=np.load(f'pass_1/cls_hidden_L{l}.npy'); he=np.load(f'pass_{k}/cls_hidden_L{l}.npy')
            out.append(round(1-((he-hb)**2).sum()/((hb-hb.mean(0))**2).sum(),4))
        except Exception as e: out.append(None)
    d=dict(agree=(pb==pe).mean(),low=(pb==pe)[low].mean(),R2=round(r2,4),acc=(pe==lab1).mean(),F1=round(f1(pe,lab1),4),clsR2=out)
    if verbose: print(k,d)
    return d
'''
open('evalh.py','w').write(src)
exec(src)
print('base acc',(Lb.argmax(1)==lab1).mean(), f1(Lb.argmax(1),lab1))
for k in [12,13,17]: stats(k)
